const C=FrostCore,KEY='frost_learning_os_v1_state';let state=load(),current=null;function load(){try{return C.normalizeState(JSON.parse(localStorage.getItem(KEY))||C.initialState())}catch{return C.initialState()}}function save(){localStorage.setItem(KEY,JSON.stringify(state))}function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function fmt(p){return Math.round(p*100)+'%'}function eventId(){return globalThis.crypto&&typeof globalThis.crypto.randomUUID==='function'?globalThis.crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}function selectTab(id){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));document.querySelectorAll('.panel').forEach(x=>x.hidden=x.id!==id);if(id==='teacher')renderTeacher();if(id==='evidence')renderEvidence()}function renderStudent(){current=C.nextQuestion(state);const p=C.masteryProb(state.mastery[current.skill]),rp=C.readinessProb(state.mastery[current.skill]),m=state.mastery[current.skill];document.querySelector('#skill').textContent=C.SKILLS[current.skill].label+' · '+C.SKILLS[current.skill].standard;document.querySelector('#mastery').textContent='Historical mastery '+fmt(p)+' · current readiness '+fmt(rp)+' · independent correct items '+C.independentCorrectCount(m)+' · '+(C.masteryReady(state,current.skill)?'READY':C.retentionRequired(m)?'RETENTION CHECK DUE':'BUILDING EVIDENCE');document.querySelector('#question').textContent=current.prompt;document.querySelector('#answer').value='';document.querySelector('#feedback').innerHTML=''}function submit(){const response=document.querySelector('#answer').value;if(!response.trim())return;const result=C.updateState(state,current,response),ev=C.appendEvidence(state,{id:eventId(),at:new Date().toISOString(),type:'ANSWER_SUBMITTED',question_id:current.id,skill:current.skill,response,correct:result.ok,diagnosis:result.diagnosis.code,confidence:result.diagnosis.confidence,mastery_after:result.mastery,readiness_after:result.readiness});save();document.querySelector('#feedback').innerHTML=`<div class="${result.ok?'ok':'bad'}"><b>${result.ok?'Correct':'Not yet'}</b> — ${esc(result.diagnosis.message)}</div><div class="intervention"><b>${esc(result.intervention.type)}</b>: ${esc(result.intervention.text)}</div><small>Evidence ${esc(ev.hash.slice(0,12))}…</small><div><button id="nextBtn">Next adaptive question</button></div>`;document.querySelector('#nextBtn').onclick=renderStudent}function hint(){const i=C.intervention({code:'UNCLASSIFIED_ERROR'},current.skill);document.querySelector('#feedback').innerHTML=`<div class="intervention"><b>Hint:</b> ${esc(i.text)}</div>`;C.appendEvidence(state,{id:eventId(),at:new Date().toISOString(),type:'HINT_REQUESTED',question_id:current.id,skill:current.skill});save()}function renderTeacher(){const rows=C.teacherPriorities(state);document.querySelector('#teacherRows').innerHTML=rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.standard)}</td><td>${fmt(r.mastery)}</td><td>${r.observations}</td><td>${r.independentCorrects}</td><td>${fmt(r.readiness)} · ${r.ready?'READY':r.retentionDue?'RETENTION DUE':'BUILDING'}</td><td>${esc(r.misconception||'—')}</td><td><b>${r.priority}</b></td></tr>`).join('');const top=rows[0];document.querySelector('#teacherAction').innerHTML=`<b>Highest-priority action:</b> ${esc(top.label)} — ${top.misconception?`address ${esc(top.misconception)}`:'collect one discriminating observation'}; historical mastery ${fmt(top.mastery)}; current readiness ${fmt(top.readiness)}.`}function renderEvidence(){const e=[...state.evidence].reverse(),integrity=C.verifyEvidenceChain(state);document.querySelector('#evidenceCount').textContent=e.length+' local evidence events · chain '+(integrity.ok?'VERIFIED':'FAILED');document.querySelector('#evidenceList').innerHTML=e.slice(0,30).map(x=>`<li><code>${esc((x.hash||'').slice(0,10))}</code> ${esc(x.type)} · ${esc(x.skill||'system')} · ${esc(x.at)}</li>`).join('')||'<li>No evidence yet.</li>'}function exportData(){const json=JSON.stringify({exported_at:new Date().toISOString(),integrity:C.verifyEvidenceChain(state),state},null,2);if(window.FrostAndroid&&typeof window.FrostAndroid.exportEvidence==='function'){window.FrostAndroid.exportEvidence(json);return}const blob=new Blob([json],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='frost-learning-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function resetData(){if(confirm('Reset local learner evidence?')){state=C.initialState();save();renderStudent();renderTeacher();renderEvidence()}}document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));document.querySelector('#submit').onclick=submit;document.querySelector('#hint').onclick=hint;document.querySelector('#answer').addEventListener('keydown',e=>{if(e.key==='Enter')submit()});document.querySelector('#export').onclick=exportData;document.querySelector('#reset').onclick=resetData;renderStudent();renderTeacher();renderEvidence();
